import Card from 'react-bootstrap/Card';


function card() {
    return (
      <Card className='block1'>
         <Card.Img variant="top" src="holder.js/100px180?text=Image cap"/>
        <Card.Body>
          <Card.Title>UX design</Card.Title>
          <Card.Text>
            L'UX Design est une discipline qui consiste à concevoir
            des produits(sites web, applications mobiles, logiciels,etc.)en plaçant
            l'utilisateur au centre des préoccupations.L'objectif est 
            de rendre l'expérience utilisateur la plus fluide et agréable possible.          
          </Card.Text>
        </Card.Body>
      </Card>
    );
  }
  
  export default card;
